    public static void testTheWordsOfEveryEnumKeyAreRead() {
        emon.Enctx.Cfg a = new emon.Enctx.Cfg();
        emon.Enctx.Cfg b = new emon.Enctx.Cfg();
        emon.Enctx.Cfg d = new emon.Enctx.Cfg();
        emon.Enctx.Cfg e = new emon.Enctx.Cfg();
        tParse(a, emon.Testport.textBlob("ocr=always\nfurniture=policy\nassets=none\nasset-signatures=off\nocr-scope=full"));
        emon.Testport.assertEq(a.ocr, 2, "always");
        emon.Testport.assertEq(a.furn, 0, "policy");
        emon.Testport.assertEq(a.level, 0, "none");
        emon.Testport.assertEq(a.sigs, 0, "off");
        emon.Testport.assertEq(a.scope, 0, "full");
        tParse(b, emon.Testport.textBlob("ocr=auto\nfurniture=keep\nassets=images"));
        emon.Testport.assertEq(b.ocr, 1, "auto");
        emon.Testport.assertEq(b.furn, 1, "keep");
        emon.Testport.assertEq(b.level, 1, "images");
        tParse(d, emon.Testport.textBlob("keep-evidence=0\nrecord=yes\njs-ocr=11"));
        emon.Testport.assertEq(d.keep, 0, "a flag is 1 or nothing");
        emon.Testport.assertEq(d.rec, 0, "yes is not 1");
        emon.Testport.assertEq(d.jsocr, 0, "11 is not 1");
        tParse(e, emon.Testport.textBlob("keep-evidence=1"));
        emon.Testport.assertEq(e.keep, 1, "one");
    }
